public static void main(Args args)
{
    METCustLicDueEmailSendController controller = new METCustLicDueEmailSendController();
    
    controller.parmArgs(args);
    controller.initContract();
    controller.startOperation();
}

public static METCustLicDueEmailSendController construct()
{
    return new METCustLicDueEmailSendController();
}

private void initContract()
{
    DictMethod dictMethod = new SysDictMethod(UtilElementType::ClassInstanceMethod, className2Id(this.parmClassName()), this.parmMethodName());
    str dataContractKey = dictMethod.parameterName(1);
        
    METCustLicDueEmailSendContract contract = this.getDataContractObject(dataContractKey) as METCustLicDueEmailSendContract;
    contract.parmCustomerLicenceDueRecIds(this.parmArgs().parm());
}
